parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "address": { "type": "string", "description": "Delivery street address or ZIP code. Empty string if not given." },
    "party_size": { "type": "number", "description": "Number of people to feed. 0 if not given." },
    "budget_usd": { "type": "number", "description": "Total budget in US dollars. 0 if not given." },
    "preferences": { "type": "array", "items": { "type": "string" }, "description": "Preferred toppings or pizza styles, lowercase." },
    "dietary_restrictions": { "type": "array", "items": { "type": "string" }, "description": "Dietary restrictions such as vegetarian, vegan, gluten-free. Empty array if none." },
    "desired_delivery_time": { "type": "string", "description": "Desired delivery time or maximum wait as written by the user. Empty string if not given." },
    "follow_up_question": { "type": "string", "description": "A single short question asking for the missing essential information. Empty string if nothing essential is missing." }
  },
  "required": ["address", "party_size", "budget_usd", "preferences", "dietary_restrictions", "desired_delivery_time", "follow_up_question"]
}

