}
const request = {
  address: String(raw.address || '').trim(),
  party_size: Math.round(num(raw.party_size)),
  budget_usd: num(raw.budget_usd),
  preferences: list(raw.preferences),
  dietary_restrictions: list(raw.dietary_restrictions),
  desired_delivery_time: String(raw.desired_delivery_time || '').trim(),
};
const missing = [];
if (!request.address) missing.push('a delivery address or ZIP code');
if (!(request.party_size > 0)) missing.push('how many people you are feeding');
if (!(request.budget_usd > 0)) missing.push('your total budget in USD');
const complete = missing.length === 0;
let reply = '';
if (!complete) {
  reply = String(raw.follow_up_question || '').trim();
  if (!reply) reply = 'To find the best pizza deal I still need ' + missing.join(', ') + '.';
