const dd = storesOf(readAll('Search DoorDash'), 'DoorDash search');
const ue = storesOf(readAll('Search Uber Eats'), 'Uber Eats search');
const PER_PLATFORM = 4;
function looksLikePizza(s) {
  const text = [s.name, s.description].filter(Boolean).join(' ');
  return /pizz|pie|slice|italian/i.test(text);
}
