}
const out = [];
const ddOpen = dd.filter(function (s) { return s.id && s.open_now !== false && s.delivery_available !== false; });
rank(ddOpen).slice(0, PER_PLATFORM).forEach(function (s) {
  out.push({ json: {
    platform: 'DoorDash', store_id: String(s.id), store_url: s.url || null, restaurant: s.name || null,
