    eta_min: typeof s.eta_minutes === 'number' ? s.eta_minutes : null,
    eta_max: typeof s.eta_minutes === 'number' ? s.eta_minutes : null,
    offers: [], dashpass: s.dashpass === true, request: request,
  } });
});
const ueOpen = ue.filter(function (s) { return s.id && s.accepting_orders !== false; });
rank(ueOpen).slice(0, PER_PLATFORM).forEach(function (s) {
  out.push({ json: {
    platform: 'Uber Eats', store_id: String(s.id), store_url: s.url || null, restaurant: s.name || null,
    rating: s.rating === undefined ? null : s.rating, rating_count: s.rating_count === undefined ? null : s.rating_count,
    search_delivery_fee: typeof s.delivery_fee === 'number' ? s.delivery_fee : null,
