// DEMO / MOCK DATA: used only when no live DoorDash or Uber Eats stores could be loaded.
// Every value below is fictional and is labelled source = "mock".
const reasons = ($input.first().json.errors) || [];
function row(platform, restaurant, id, item, size, diameter, price, fee, svc, eta, minSubtotal) {
