  row('DoorDash', 'Demo Slice House', 'dsh-dd', 'Large Cheese Pizza', 'Large', 14, 16.99, 3.99, null, 35, 10),
  row('DoorDash', 'Demo Slice House', 'dsh-dd', 'Medium Cheese Pizza', 'Medium', 12, 13.99, 3.99, null, 35, 10),
  row('Uber Eats', 'Demo Slice House', 'dsh-ue', 'Large Pepperoni Pizza', 'Large', 14, 19.49, 2.49, 3.0, 30, null),
  row('Uber Eats', 'Demo Slice House', 'dsh-ue', 'Large Cheese Pizza', 'Large', 14, 17.49, 2.49, 3.0, 30, null),
  row('DoorDash', 'Mock Pie Palace', 'mpp-dd', 'XL Pepperoni Pizza', 'Extra Large', 16, 22.99, 0, null, 45, 15),
  row('DoorDash', 'Mock Pie Palace', 'mpp-dd', 'XL Cheese Pizza', 'Extra Large', 16, 19.99, 0, null, 45, 15),
  row('DoorDash', 'Mock Pie Palace', 'mpp-dd', 'XL Supreme Pizza', 'Extra Large', 16, 24.99, 0, null, 45, 15),
  row('Uber Eats', 'Mock Corner Pizzeria', 'mcp-ue', 'Large Pepperoni Pizza', 'Large', 14, 17.5, 4.99, 2.0, 25, null),
  row('Uber Eats', 'Mock Corner Pizzeria', 'mcp-ue', 'Large Margherita Pizza', 'Large', 14, 16.0, 4.99, 2.0, 25, null),
  row('Uber Eats', 'Mock Corner Pizzeria', 'mcp-ue', 'Large Veggie Pizza', 'Large', 14, 18.0, 4.99, 2.0, 25, null),
];
return rows.map(function (r) { return { json: r }; });

const stores = $('Select Top Pizzerias').all().map(function (i) { return i.json; });
const responses = $input.all();
const rows = [];
const errors = [];
const SKIP_KEYS = { raw: 1, reviews: 1, images: 1, hours: 1, delivery_hours: 1, badges: 1 };
const NOT_PIZZA = /slice|calzone|sauce|dessert|cookie|brownie|wing|salad|drink|soda|water|juice|garlic|knot|bread|pasta|stromboli|dip|dressing|cheesecake|cannoli|fries|lasagna|sandwich|sub[ ]|pakora|taco|mango lassi|samosa|naan|burger|nugget|popper|mozzarella stick|roll|bites/i;
