  if (Array.isArray(node.items) && typeof node.name === 'string' && typeof node.price !== 'number') {
    collect(node.items, node.name, acc);
    return;
  }
  if (typeof node.name === 'string' && typeof node.price === 'number') {
    acc.push({ item: node, category: category });
    return;
