  return n >= 4 && n <= 24 ? n : null;
}
function parseSize(text) {
  const t = text.toLowerCase();
  if (/extra[ -]large|x-large|xl/.test(t)) return 'Extra Large';
  if (/personal|individual/.test(t)) return 'Personal';
  if (/small/.test(t)) return 'Small';
  if (/medium/.test(t)) return 'Medium';
  if (/large/.test(t)) return 'Large';
